import { useReducedMotion } from "motion/react";
import { LazyMotion, domAnimation, m } from "motion/react";

export type PainFreeTreatmentProps = {
  eyebrow: string;
  title: string;
  text: string;
  image: { src: string; alt: string };
};

export default function PainFreeTreatment({
  eyebrow,
  title,
  text,
  image,
}: PainFreeTreatmentProps) {
  const reducedMotion = useReducedMotion();

  return (
    <LazyMotion features={domAnimation}>
      <section className="bg-background font-sans text-foreground">
        <div className="mx-auto grid w-full max-w-page grid-cols-1 items-center gap-8 px-gutter py-section md:grid-cols-2 md:gap-12">
          <m.div
            className="order-2 min-w-0 md:order-1"
            initial={reducedMotion ? undefined : { opacity: 0, x: -20 }}
            whileInView={reducedMotion ? undefined : { opacity: 1, x: 0 }}
            viewport={{ once: true, amount: 0.3 }}
            transition={{ duration: 0.6, ease: "easeOut" }}
          >
            <span className="block text-small font-bold uppercase tracking-wide text-muted-foreground">
              {eyebrow}
            </span>
            <h2 className="mt-2 font-display text-h2 font-bold text-balance wrap-break-word">
              {title}
            </h2>
            <p className="mt-4 text-body text-muted-foreground text-balance wrap-break-word">
              {text}
            </p>
          </m.div>

          <m.div
            className="order-1 min-w-0 md:order-2"
            initial={reducedMotion ? undefined : { opacity: 0, x: 20 }}
            whileInView={reducedMotion ? undefined : { opacity: 1, x: 0 }}
            viewport={{ once: true, amount: 0.3 }}
            transition={{ duration: 0.6, ease: "easeOut" }}
          >
            <div className="overflow-hidden rounded-lg">
              <img
                src={image.src}
                alt={image.alt}
                className="h-auto w-full object-cover"
                loading="lazy"
              />
            </div>
          </m.div>
        </div>
      </section>
    </LazyMotion>
  );
}

