export default function WhyPainless({ title, items, image, cta }: WhyPainlessProps) {
  const prefersReducedMotion = useReducedMotion();
  const shouldAnimate = !prefersReducedMotion;
  const id = useId();

  return (
    <LazyMotion features={domAnimation}>
      <section className="bg-background font-sans text-foreground">
        <div className="mx-auto flex w-full max-w-page flex-col gap-10 px-gutter py-section md:flex-row md:items-center md:gap-14">
          {/* Image */}
          <m.div
            initial={shouldAnimate ? { opacity: 0, x: -20 } : undefined}
            whileInView={shouldAnimate ? { opacity: 1, x: 0 } : undefined}
            viewport={{ once: true, margin: "-80px" }}
            transition={{ duration: 0.5, ease: "easeOut" }}
            className="relative w-full shrink-0 md:w-1/2"
          >
            <div className="overflow-hidden rounded-lg">
              <img
                src={image.src}
                alt={image.alt}
                className="aspect-[4/3] w-full object-cover"
                loading="lazy"
              />
            </div>
          </m.div>

          {/* Content */}
          <div className="flex w-full min-w-0 flex-col md:w-1/2">
            <m.h2
              initial={shouldAnimate ? { opacity: 0, y: 12 } : undefined}
              whileInView={shouldAnimate ? { opacity: 1, y: 0 } : undefined}
              viewport={{ once: true, margin: "-80px" }}
              transition={{ duration: 0.4, ease: "easeOut" }}
              className="font-display text-h2 font-bold text-balance wrap-break-word"
            >
              {title}
            </m.h2>

            <div className="mt-6 flex flex-col gap-6">
              {items.map((item, index) => (
                <m.div
                  key={`${id}-${index}`}
                  initial={shouldAnimate ? { opacity: 0, y: 10 } : undefined}
                  whileInView={shouldAnimate ? { opacity: 1, y: 0 } : undefined}
                  viewport={{ once: true, margin: "-60px" }}
                  transition={{
                    duration: 0.35,
                    ease: "easeOut",
                    delay: index * 0.1,
                  }}
                >
                  <h3 className="font-display text-h3 font-semibold text-foreground">
                    {item.title}
                  </h3>
                  <p className="mt-1 text-body text-muted-foreground">
                    {item.text}
                  </p>
                </m.div>
              ))}
            </div>

            <m.div
              initial={shouldAnimate ? { opacity: 0, y: 10 } : undefined}
              whileInView={shouldAnimate ? { opacity: 1, y: 0 } : undefined}
              viewport={{ once: true, margin: "-60px" }}
              transition={{ duration: 0.35, ease: "easeOut", delay: 0.25 }}
              className="mt-8"
            >
              <a
                href={cta.href}
                className="inline-flex min-h-11 min-w-11 items-center justify-center rounded-control bg-primary px-6 text-center text-body font-bold text-primary-foreground transition-opacity duration-200 hover:opacity-90 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring"
              >
                {cta.label}
              </a>
            </m.div>
          </div>
        </div>
      </section>
    </LazyMotion>
  );
}

