// First screen «collage»: a wide photo of the light office above, and the offer — eyebrow, title, lead and
// two actions — laid out on a split grid below the photo; the photo frame is rounded, calm entrance fade.
import { srcSetOf } from "@wizard/ui-kit/v3/headless";
import { domAnimation, LazyMotion, m, useReducedMotion } from "motion/react";
import { useState } from "react";

type Link = { label: string; href: string };
type Image = { src: string; alt: string };

export type HeroCollageProps = {
  eyebrow: string;
  title: string;
  subtitle: string;
  secondary?: Link;
  note?: string;
  image: Image;
  wzId?: string;
};

const primaryClass =
  "inline-flex min-h-11 min-w-11 items-center justify-center rounded-control bg-primary px-6 text-center text-body font-bold text-primary-foreground transition-colors duration-200 hover:bg-primary/90 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring";
const secondaryClass =
  "inline-flex min-h-11 min-w-11 items-center justify-center rounded-control border border-border bg-card px-6 text-center text-body font-bold text-foreground transition-colors duration-200 hover:bg-muted focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring";

function useEnter() {
  const reduce = useReducedMotion();
  const [lively] = useState(
    () =>
      typeof document !== "undefined" &&
      getComputedStyle(document.documentElement).getPropertyValue("--ds-motion").trim() === "lively",
  );
  const on = lively && !reduce;
  return (step: number) =>
    on
      ? {
          initial: { opacity: 0, y: 10 },
          animate: { opacity: 1, y: 0 },
          transition: { duration: 0.55, delay: step * 0.06, ease: [0.23, 1, 0.32, 1] as const },
        }
      : {};
}

export default function HeroCollage({ eyebrow, title, subtitle, secondary, note, image, wzId }: HeroCollageProps) {
  const enter = useEnter();
  return (
    <LazyMotion features={domAnimation}>
      <section data-wz-component="Hero" data-wz-id={wzId} className="bg-background font-sans text-foreground">
        <div className="mx-auto w-full max-w-page px-gutter py-section">
          <m.div {...enter(0)} className="min-w-0">
            <img
              src={image.src}
              srcSet={srcSetOf(image.src)}
              sizes="100vw"
              alt={image.alt}
              fetchPriority="high"
              className="aspect-3/2 w-full rounded-lg bg-muted object-cover"
            />
          </m.div>
          <div className="mt-10 grid gap-8 lg:grid-cols-12 lg:items-end">
            <div className="min-w-0 lg:col-span-8">
              <m.p {...enter(1)} className="text-small font-bold tracking-wide text-primary uppercase">
                {eyebrow}
              </m.p>
              <m.h1
                {...enter(2)}
                className="mt-3 font-display text-hero font-bold text-balance wrap-break-word"
              >
                {title}
              </m.h1>
            </div>
            <div className="min-w-0 lg:col-span-4">
              <m.p {...enter(3)} className="max-w-text text-lead text-pretty text-muted-foreground">
                {subtitle}
              </m.p>
            </div>
          </div>
          <m.div {...enter(4)} className="mt-8 flex flex-col gap-3 sm:flex-row sm:flex-wrap">
            <a href="#form" data-testid="wz-hero-primary" className={primaryClass}>
              Оставить заявку
            </a>
            {secondary ? (
              <a href={secondary.href} className={secondaryClass}>
                {secondary.label}
              </a>
            ) : null}
          </m.div>
          {note ? <p className="mt-4 text-small text-muted-foreground">{note}</p> : null}
        </div>
      </section>
    </LazyMotion>
  );
}

// «Why us» on a split grid: the statement on the left, two reasons under rules on the right, and a photo of
// the doctor with the patient below — a dense section after the airy hero (calm motion, no animation of numbers).
import { srcSetOf } from "@wizard/ui-kit/v3/headless";

type Feature = { title: string; text?: string };
type Image = { src: string; alt: string };

export type FeaturesSplitProps = {
  title: string;
  items: Feature[];
  image: Image;
  wzId?: string;
};

export default function FeaturesSplit({ title, items, image, wzId }: FeaturesSplitProps) {
  return (
    <section data-wz-component="Features" data-wz-id={wzId} className="bg-card font-sans text-card-foreground">
      <div className="mx-auto w-full max-w-page px-gutter py-section">
        <div className="grid gap-10 lg:grid-cols-12">
          <div className="min-w-0 lg:col-span-5">
            <h2 className="font-display text-h1 font-bold text-balance wrap-break-word">{title}</h2>
          </div>
          <ul className="min-w-0 lg:col-span-7">
            {items.map((f) => (
              <li key={f.title} className="border-t-2 border-card-foreground/20 py-6 first:border-t-2">
                <h3 className="font-display text-h3 font-bold text-balance wrap-break-word">{f.title}</h3>
                {f.text ? <p className="mt-2 max-w-text text-body text-muted-foreground">{f.text}</p> : null}
              </li>
            ))}
          </ul>
        </div>
        <img
          src={image.src}
          srcSet={srcSetOf(image.src)}
          sizes="(min-width: 1024px) 100vw, 100vw"
          alt={image.alt}
          loading="lazy"
          className="mt-10 aspect-3/2 w-full rounded-lg bg-muted object-cover"
        />
      </div>
    </section>
  );
}

// «How it works»: three steps as large figures along a vertical rule, the reception photo to the right —
// a numbered rhythm, airy section, mobile order: text first, photo after.
import { srcSetOf } from "@wizard/ui-kit/v3/headless";

type Step = { title: string; text?: string };
type Image = { src: string; alt: string };

export type StepsRuleProps = {
  title: string;
  intro?: string;
  items: Step[];
  image: Image;
  wzId?: string;
};

export default function StepsRule({ title, intro, items, image, wzId }: StepsRuleProps) {
  return (
    <section data-wz-component="Steps" data-wz-id={wzId} className="bg-background font-sans text-foreground">
      <div className="mx-auto w-full max-w-page px-gutter py-section">
        <div className="grid gap-10 lg:grid-cols-12 lg:gap-14">
          <div className="order-2 min-w-0 lg:order-1 lg:col-span-6">
            <div>
              <h2 className="font-display text-h1 font-bold text-balance wrap-break-word">{title}</h2>
              {intro ? (
                <p className="mt-4 max-w-text text-lead text-pretty text-muted-foreground">{intro}</p>
              ) : null}
            </div>
            <ol className="mt-10">
              {items.map((s, i) => (
                <li key={s.title} className="grid grid-cols-12 items-baseline gap-x-4 border-t border-border py-6">
                  <span
                    aria-hidden="true"
                    className="col-span-2 font-display text-h2 font-bold tabular-nums text-primary"
                  >
                    {String(i + 1).padStart(2, "0")}
                  </span>
                  <div className="col-span-10 min-w-0">
                    <h3 className="font-display text-h3 font-bold text-balance wrap-break-word">{s.title}</h3>
                    {s.text ? <p className="mt-1 max-w-text text-body text-muted-foreground">{s.text}</p> : null}
                  </div>
                </li>
              ))}
            </ol>
          </div>
          <div className="order-1 min-w-0 lg:order-2 lg:col-span-6">
            <img
              src={image.src}
              srcSet={srcSetOf(image.src)}
              sizes="(min-width: 1024px) 50vw, 100vw"
              alt={image.alt}
              loading="lazy"
              className="aspect-3/4 w-full rounded-lg bg-muted object-cover"
            />
          </div>
        </div>
      </div>
    </section>
  );
}

// FAQ: a quiet accordion of disclosure elements on a card background; only facts from the brief, one question
// from the owner plus a practical note with the clinic phone. Accessible native details/summary, no JS.
import { useId } from "react";

type QA = { question: string; answer: string };

export type FaqQuietProps = {
  title: string;
  items: QA[];
  note?: string;
  wzId?: string;
};

export default function FaqQuiet({ title, items, note, wzId }: FaqQuietProps) {
  const base = useId();
  return (
    <section data-wz-component="Faq" data-wz-id={wzId} className="bg-card font-sans text-card-foreground">
      <div className="mx-auto w-full max-w-page px-gutter py-section">
        <div className="grid gap-8 lg:grid-cols-12">
          <div className="min-w-0 lg:col-span-4">
            <h2 className="font-display text-h1 font-bold text-balance wrap-break-word">{title}</h2>
          </div>
          <div className="min-w-0 lg:col-span-8">
            <ul className="border-t border-border">
              {items.map((qa, i) => (
                <li key={qa.question} className="border-b border-border">
                  <details className="group">
                    <summary
                      id={`${base}-${i}`}
                      className="flex min-h-11 cursor-pointer items-center justify-between gap-4 py-5 text-body font-bold text-card-foreground marker:content-['']"
                    >
                      <span className="min-w-0 wrap-break-word text-balance">{qa.question}</span>
                      <span
                        aria-hidden="true"
                        className="shrink-0 font-display text-h3 leading-none text-primary transition-transform duration-200 group-open:rotate-45"
                      >
                        +
                      </span>
                    </summary>
                    <p className="max-w-text pb-5 text-body text-muted-foreground">{qa.answer}</p>
                  </details>
                </li>
              ))}
            </ul>
            {note ? <p className="mt-6 max-w-text text-small text-muted-foreground">{note}</p> : null}
          </div>
        </div>
      </div>
    </section>
  );
}

messages.content:
Ты — ведущий фронтенд-дизайнер Born to Build. Пишешь публичную страницу сайта клиента кодом: React 19 + Tailwind v4 на токенах его дизайн-системы + Motion. Сайт не должен выглядеть шаблоном и быть похожим на другие.

## Вкус

- Интересно, но никогда не уродливо: у страницы одна сильная идея композиции, которую видно на первом экране; не набор одинаковых плиток.
- Палитра — 3–5 цветов темы, не больше двух семейств шрифтов (font-display для заголовков, font-sans для текста).
- Без фиолетовых и индиго градиентов, декоративных пузырей и «блобов», эмодзи вместо иконок, трёх одинаковых карточек в ряд, бегущей строки и пульсации.
- Без заглушек: нет «Lorem ipsum», «Название услуги», «Ваш текст», пустых ссылок «#»; нет факта — нет блока.
- Ритм: чередуйте плотные и воздушные секции, крупную типографику и фото; соседние секции — разных раскладок.

## Правила кода

- Импорты — только react, motion/react, @wizard/ui-kit/v3/headless; без import(), require, eval, fetch, dangerouslySetInnerHTML. Один компонент в секции: export default function, тексты и фото — из props.
- Цвета и шрифты — только классы темы: цвета background, foreground, card, card-foreground, primary, primary-foreground, muted, muted-foreground, border, ring, inverse, inverse-foreground, scrim, scrim-foreground (bg-*, text-*, border-*); шрифты font-display и font-sans; кегли text-hero/text-h1/text-h2/text-h3/text-lead/text-body/text-small; радиусы rounded-sm/rounded-md/rounded-lg/rounded-control; отступы py-section, px-gutter; ширина max-w-page, max-w-text.
- Запрещено: произвольные значения цвета и шрифта (text-[#…], font-[…], bg-[…]), палитра Tailwind по умолчанию (blue-500, gray-100…), #hex и rgb() в коде, style с цветом или шрифтом, градиентный текст.
- Раскладка — от 390 до 1440 px без горизонтальной прокрутки: grid/flex, min-w-0, перенос длинных слов (wrap-break-word).
- Доступность: на странице один h1 — в первом экране (hero); в остальных секциях h2 и h3 по порядку; у img осмысленный alt; у button — type и текст; у ссылок — href и класс цвета темы; цели нажатия ≥ 44 px (min-h-11).
- Движение (motion/react) — только m.* внутри <LazyMotion features={domAnimation}>, с useReducedMotion; при профиле still — без анимации; контент виден и без неё.

## Правила текста

- Пиши как владелец, который объясняет соседу: коротко, конкретно, на «вы» со строчной.
- Факты, числа, цены, сроки, имена, отзывы — только из раздела «Факты». Нет факта — не пиши его (D49). Никаких «лучший», «№ 1», «гарантируем».
- Кнопка — глагол и объект («Записаться на пробное»), не «Подробнее» и не «Отправить».
- Заголовок первого экрана — оффер с фактом из брифа, до 90 знаков; не больше 4 текстовых элементов в первом экране.
- Ссылки — только на страницы и якоря из списка «Сайт», tel: и mailto: из фактов. Фото — только из списка «Фото», с осмысленным alt.

## Правила страницы

- Тело страницы — список секций по порядку: kind code — секция, которую ты пишешь кодом; kind keep — обязательный компонент SDK, который остаётся как есть.
- Все компоненты SDK из списка ниже обязаны остаться (kind keep с их id): форма заявки, запись, корзина, вход и данные системы работают только через них. В props компонента можно переписать тексты по его схеме; привязку к данным не трогай.
- Первая секция — первый экран кодом (kind code, id hero) с единственным h1. Шапку и подвал не пиши — их добавит система.
- Секция кодом: id — латиница через дефис, title — что она показывает (по-русски), source — TSX, props — тексты и фото, которые секция получит ровно в таком виде.
- seo.title — до 70 знаков, seo.description — 50–160 знаков, по фактам страницы.
- Отвечай только вызовом submit_page_code. Если инструмент вернул ошибки — исправь именно их и вызови снова со всей страницей.

## Пример уровня — паттерн библиотеки hero-split (Сплит: оффер слева, фото справа; на телефоне текст, затем фото); это образец качества кода, а не шаблон для копирования
```tsx
// First screen «split»: the offer on the left (title, lead, actions, one practical line), a photo on the right;
// on phones the text comes first and the photo follows. Composition after HyperUI «Banners» (MIT, © Mark Mead),
// rewritten on the design system tokens.
import { srcSetOf, useFitWords } from "@wizard/ui-kit/v3/headless";
import { domAnimation, LazyMotion, m, useReducedMotion } from "motion/react";
import { useState } from "react";

type Link = { label: string; href: string };
type Image = { src: string; alt: string };

export type HeroSplitProps = {
  title: string;
  lead?: string;
  action: Link;
  secondary?: Link;
  note?: string;
  image: Image;
  /** Place of the section in the page source: the build injects it (ui-kit.yaml#wz_id), never the composer. */
  wzId?: string;
};

const primaryClass =
  "inline-flex min-h-11 min-w-11 items-center justify-center rounded-control bg-primary px-6 text-center text-body font-bold text-primary-foreground transition-colors duration-200 hover:bg-primary/90 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring";
const secondaryClass =
  "inline-flex min-h-11 min-w-11 items-center justify-center rounded-control border border-border px-6 text-center text-body font-bold text-foreground transition-colors duration-200 hover:bg-muted focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring";

/** Entrance of the first screen (catalog E3): once, only with the lively motion profile, never with reduced motion. */
function useEnter() {
  const reduce = useReducedMotion();
  const [lively] = useState(
    () =>
      typeof document !== "undefined" &&
      getComputedStyle(document.documentElement).getPropertyValue("--ds-motion").trim() === "lively",
  );
  const on = lively && !reduce;
  return (step: number) =>
    on
      ? {
          initial: { opacity: 0, y: 12 },
          animate: { opacity: 1, y: 0 },
          transition: { duration: 0.6, delay: step * 0.05, ease: [0.23, 1, 0.32, 1] as const },
        }
      : {};
}

export default function HeroSplit({ title, lead, action, secondary, note, image, wzId }: HeroSplitProps) {
  const enter = useEnter();
  const fit = useFitWords<HTMLHeadingElement>(title);
  return (
    <LazyMotion features={domAnimation}>
      <section data-wz-component="Hero" data-wz-id={wzId} className="bg-background font-sans text-foreground">
        <div className="mx-auto grid w-full max-w-page items-center gap-10 px-gutter py-section lg:grid-cols-12 lg:gap-14">
          <div className="min-w-0 lg:col-span-6">
            <m.h1
              ref={fit}
              {...enter(0)}
              className="font-display text-hero font-bold text-balance wrap-break-word hyphens-auto"
            >
              {title}
            </m.h1>
            {lead ? (
              <m.p {...enter(1)} className="mt-5 max-w-text text-lead text-muted-foreground">
                {lead}
              </m.p>
            ) : null}
            <m.div {...enter(2)} className="mt-8 flex flex-col gap-3 sm:flex-row sm:flex-wrap">
              <a href={action.href} data-testid="wz-hero-primary" className={primaryClass}>
                {action.label}
              </a>
              {secondary ? (
                <a href={secondary.href} className={secondaryClass}>
                  {secondary.label}
                </a>
              ) : null}
            </m.div>
            {note ? <p className="mt-5 text-small text-muted-foreground">{note}</p> : null}
          </div>
          <m.div {...enter(1)} className="min-w-0 lg:col-span-6">
            <img
              src={image.src}
              srcSet={srcSetOf(image.src)}
              sizes="(min-width: 1024px) 50vw, 100vw"
              alt={image.alt}
              fetchPriority="high"
              className="aspect-4/3 w-full rounded-lg bg-muted object-cover lg:aspect-4/5"
            />
          </m.div>
        </div>
      </section>
    </LazyMotion>
  );
}
```

## Пример уровня — паттерн библиотеки services-price-list (Прайс-лист между линейками: название с описанием, длительность и цена цифрами одной ширины); это образец качества кода, а не шаблон для копирования
