                    {s.text ? <p className="mt-1 max-w-text text-body text-muted-foreground">{s.text}</p> : null}
                  </div>
                </li>
              ))}
            </ol>
          </div>
          <div className="order-1 min-w-0 lg:order-2 lg:col-span-6">
            <img
              src={image.src}
              srcSet={srcSetOf(image.src)}
              sizes="(min-width: 1024px) 50vw, 100vw"
              alt={image.alt}
              loading="lazy"
              className="aspect-3/4 w-full rounded-lg bg-muted object-cover"
            />
          </div>
        </div>
      </div>
    </section>
  );
}

// FAQ: a quiet accordion of disclosure elements on a card background; only facts from the brief, one question
// from the owner plus a practical note with the clinic phone. Accessible native details/summary, no JS.
import { useId } from "react";

type QA = { question: string; answer: string };

export type FaqQuietProps = {
  title: string;
  items: QA[];
  note?: string;
  wzId?: string;
};

export default function FaqQuiet({ title, items, note, wzId }: FaqQuietProps) {
  const base = useId();
  return (
    <section data-wz-component="Faq" data-wz-id={wzId} className="bg-card font-sans text-card-foreground">
      <div className="mx-auto w-full max-w-page px-gutter py-section">
        <div className="grid gap-8 lg:grid-cols-12">
          <div className="min-w-0 lg:col-span-4">
            <h2 className="font-display text-h1 font-bold text-balance wrap-break-word">{title}</h2>
          </div>
          <div className="min-w-0 lg:col-span-8">
            <ul className="border-t border-border">
              {items.map((qa, i) => (
                <li key={qa.question} className="border-b border-border">
                  <details className="group">
                    <summary
                      id={`${base}-${i}`}
                      className="flex min-h-11 cursor-pointer items-center justify-between gap-4 py-5 text-body font-bold text-card-foreground marker:content-['']"
                    >
                      <span className="min-w-0 wrap-break-word text-balance">{qa.question}</span>
                      <span
                        aria-hidden="true"
                        className="shrink-0 font-display text-h3 leading-none text-primary transition-transform duration-200 group-open:rotate-45"
                      >
                        +
                      </span>
                    </summary>
                    <p className="max-w-text pb-5 text-body text-muted-foreground">{qa.answer}</p>
                  </details>
                </li>
              ))}
            </ul>
            {note ? <p className="mt-6 max-w-text text-small text-muted-foreground">{note}</p> : null}
          </div>
        </div>
      </div>
    </section>
  );
}

