import { LazyMotion, domAnimation, m, useReducedMotion } from "motion/react";
import { useEffect, useRef, useState } from "react";

export default function Hero(props) {
  const {
    title = "Спокойная стоматология, к которой не страшно возвращаться",
    badge = "Стоматологическая клиника",
    features = ["Имплантация", "Эстетика улыбки", "Лечение без боли"],
    stats = [
      { value: "12 лет", label: "опыта команды" },
      { value: "24 ч", label: "срок ответа на заявку" },
    ],
    cards = [
      { title: "Спокойно", text: "Лечим без боли — спим, а не терпим" },
      { title: "Честно", text: "План лечения и цены до начала работы" },
      { title: "Быстро", text: "Заявка с сайта — перезвоним в течение часа" },
    ],
    photo1Src = "/_wizard/photos/00000001-0000-4000-8000-000000000001/1600",
    photo1Alt = "Врач показывает пациенту снимок на экране",
    photo2Src = "/_wizard/photos/00000000-0000-4000-8000-000000000000/1600",
    photo2Alt = "Светлый кабинет клиники с креслом у окна",
    photo3Src = "/_wizard/photos/0000 0000 0000 0000-8000-000000000002/1600",
    photo3Alt = "Стойка администратора в холле клиники",
    buttonLabel = "Записаться на приём",
    buttonHref = "#form",
  } = props;

  const reduce = useReducedMotion();
  const still = reduce ? 1 : 0;
  const [tilt, setTilt] = useState({ x: 0, y: 0 });
  const areaRef = useRef(null);

  useEffect(() => {
    if (reduce || !areaRef.current) return;
    const el = areaRef.current;
    const onMove = (e) => {
      const r = el.getBoundingClientRect();
      const x = (e.clientX - r.left) / r.width - 0.5;
      const y = (e.clientY - r.top) / r.height - 0.5;
      setTilt({ x, y });
    };
    const onLeave = () => setTilt({ x: 0, y: 0 });
    el.addEventListener("pointermove", onMove);
    el.addEventListener("pointerleave", onLeave);
    return () => {
      el.removeEventListener("pointermove", onMove);
      el.removeEventListener("pointerleave", onLeave);
    };
  }, [reduce]);

  const fade = (delay) => ({
    initial: still ? false : { opacity: 0, y: 24 },
    animate: { opacity: 1, y: 0 },
    transition: { duration: 0.7, delay, ease: [0.22, 1, 0.36, 1] },
  });

  return (
    <section
      id="hero"
      ref={areaRef}
      className="relative overflow-hidden bg-background text-foreground py-section px-gutter"
    >
      <div className="mx-auto max-w-page grid gap-12 lg:grid-cols-12 lg:gap-10 items-center">
        {/* Текстовая колонка */}
        <div className="lg:col-span-5 flex flex-col items-start gap-6">
          <m.span
            {...fade(0)}
            className="inline-flex items-center gap-2 rounded-full border border-border bg-card px-4 py-2 text-small text-card-foreground"
          >
            <span className="h-2 w-2 rounded-full bg-primary" aria-hidden="true" />
            {badge}
          </m.span>

          <m.h1
            {...fade(0.08)}
            className="font-display text-hero leading-tight tracking-tight wrap-break-word"
          >
            {title}
          </m.h1>

          <m.ul {...fade(0.16)} className="flex flex-wrap gap-2">
            {features.map((f) => (
              <li
                key={f}
                className="rounded-md border border-border bg-muted px-3 py-2 text-small text-muted-foreground"
              >
                {f}
              </li>
            ))}
          </m.ul>

          <m.div {...fade(0.24)} className="flex flex-col sm:flex-row items-stretch sm:items-center gap-4">
            <a
              href={buttonHref}
              className="inline-flex min-h-11 items-center justify-center rounded-control bg-primary px-6 text-body font-semibold text-primary-foreground transition-colors hover:bg-inverse hover:text-inverse-foreground focus-visible:outline-2 focus-visible:outline-ring"
            >
              {buttonLabel}
            </a>
            <div className="flex items-center gap-6">
              {stats.map((s) => (
                <div key={s.label} className="flex flex-col">
                  <span className="font-display text-h3 text-foreground">{s.value}</span>
                  <span className="text-small text-muted-foreground">{s.label}</span>
                </div>
              ))}
            </div>
          </m.div>

          <m.ul {...fade(0.32)} className="grid w-full gap-3 sm:grid-cols-3">
            {cards.map((c, i) => (
              <li
                key={c.title}
                className="rounded-lg border border-border bg-card p-4 text-card-foreground"
              >
                <span className="font-display text-small text-foreground">{String(i + 1).padStart(2, "0")}</span>
                <h3 className="font-display text-h3 mt-1">{c.title}</h3>
                <p className="text-small text-muted-foreground mt-1">{c.text}</p>
              </li>
            ))}
          </m.ul>
        </div>

        {/* Фотоколонка: составная композиция */}
        <div className="lg:col-span-7 relative min-h-0">
          <m.figure
            initial={still ? false : { opacity: 0, scale: 0.97 }}
            animate={{ opacity: 1, scale: 1 }}
            transition={{ duration: 0.8, ease: [0.22, 1, 0.36, 1] }}
            style={{ perspective: "1200px" }}
            className="relative"
          >
            {/* основное фото */}
            <div
              className="overflow-hidden rounded-lg border border-border bg-card"
              style={{ transform: `rotateY(${tilt.x * 2.5}deg) rotateX(${-tilt.y * 2.5}deg)` }}
            >
              <img
                src={photo1Src}
                alt={photo1Alt}
                className="aspect-[3/2] w-full object-cover"
                loading="eager"
              />
            </div>

            {/* нижний наезд — холл клиники */}
            <m.div
              initial={still ? false : { opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.7, delay: 0.25 }}
              className="absolute -bottom-8 -left-4 w-[42%] max-w-[240px] overflow-hidden rounded-lg border border-border bg-card shadow-none sm:-left-8"
            >
              <img src={photo3Src} alt={photo3Alt} className="aspect-[3/2] w-full object-cover" />
            </m.div>

            {/* кабинет у окна */}
            <m.div
              initial={still ? false : { opacity: 0, y: -20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.7, delay: 0.35 }}
              className="absolute -top-8 right-[6%] w-[30%] max-w-[180px] overflow-hidden rounded-lg border border-border bg-card"
            >
              <img src={photo2Src} alt={photo2Alt} className="aspect-[3/2] w-full object-cover" />
            </m.div>
          </m.figure>
        </div>
      </div>
    </section>
  );
}

