// Hero «split» for the price page: the offer on the left with a calm entrance, a light photo of a doctor
// showing an X-ray on the right; on phones the text comes first, the photo follows.
import { srcSetOf, useFitWords } from "@wizard/ui-kit/v3/headless";
import { domAnimation, LazyMotion, m, useReducedMotion } from "motion/react";
import { useState } from "react";

type Link = { label: string; href: string };
type Image = { src: string; alt: string };

export type HeroProps = {
  eyebrow: string;
  title: string;
  lead: string;
  primary: Link;
  note?: string;
  image: Image;
  wzId?: string;
};

const primaryClass =
  "inline-flex min-h-11 min-w-11 items-center justify-center rounded-control bg-primary px-6 text-center text-body font-bold text-primary-foreground transition-colors duration-200 hover:bg-primary/90 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring";

function useEnter() {
  const reduce = useReducedMotion();
  const [lively] = useState(
    () =>
      typeof document !== "undefined" &&
      getComputedStyle(document.documentElement).getPropertyValue("--ds-motion").trim() === "lively",
  );
  const on = lively && !reduce;
  return (step: number) =>
    on
      ? {
          initial: { opacity: 0, y: 10 },
          animate: { opacity: 1, y: 0 },
          transition: { duration: 0.55, delay: step * 0.06, ease: [0.23, 1, 0.32, 1] as const },
        }
      : {};
}

export default function Hero({ eyebrow, title, lead, primary, note, image, wzId }: HeroProps) {
  const enter = useEnter();
  const fit = useFitWords<HTMLHeadingElement>(title);
  return (
    <LazyMotion features={domAnimation}>
      <section data-wz-component="Hero" data-wz-id={wzId} className="bg-background font-sans text-foreground">
        <div className="mx-auto grid w-full max-w-page items-center gap-10 px-gutter py-section lg:grid-cols-12 lg:gap-14">
          <div className="min-w-0 lg:col-span-6">
            <m.p {...enter(0)} className="text-small font-semibold tracking-wide text-muted-foreground uppercase">
              {eyebrow}
            </m.p>
            <m.h1
              ref={fit}
              {...enter(0)}
              className="mt-3 font-display text-hero font-bold text-balance wrap-break-word hyphens-auto"
            >
              {title}
            </m.h1>
            <m.p {...enter(1)} className="mt-5 max-w-text text-lead text-pretty text-muted-foreground">
              {lead}
            </m.p>
            <m.div {...enter(2)} className="mt-8 flex flex-col gap-3 sm:flex-row sm:flex-wrap">
              <a href={primary.href} data-testid="wz-hero-primary" className={primaryClass}>
                {primary.label}
              </a>
            </m.div>
            {note ? <p className="mt-5 text-small text-muted-foreground">{note}</p> : null}
          </div>
          <m.div {...enter(1)} className="min-w-0 lg:col-span-6">
            <img
              src={image.src}
              srcSet={srcSetOf(image.src)}
              sizes="(min-width: 1024px) 50vw, 100vw"
              alt={image.alt}
              fetchPriority="high"
              className="aspect-3/2 w-full rounded-lg bg-muted object-cover"
            />
          </m.div>
        </div>
      </section>
    </LazyMotion>
  );
}

// CTA band: a calm closing strip with a small photo of the reception desk on the left, the question,
// the practical line (phone and address) and the action on the right; on phones it stacks.
import { srcSetOf } from "@wizard/ui-kit/v3/headless";

type Link = { label: string; href: string };
type Image = { src: string; alt: string };

export type CtaBandProps = {
  title: string;
  text: string;
  action: Link;
  phone: string;
  phoneHref: string;
  image: Image;
  wzId?: string;
};

const actionClass =
  "inline-flex min-h-11 min-w-11 items-center justify-center rounded-control bg-primary px-6 text-center text-body font-bold text-primary-foreground transition-colors duration-200 hover:bg-primary/90 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring";
const phoneClass =
  "inline-flex min-h-11 items-center text-body font-bold text-foreground underline decoration-primary decoration-2 underline-offset-4 transition-colors duration-200 hover:decoration-foreground focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring";

export default function CtaBand({ title, text, action, phone, phoneHref, image, wzId }: CtaBandProps) {
  return (
    <section data-wz-component="Cta" data-wz-id={wzId} className="bg-card font-sans text-card-foreground">
      <div className="mx-auto grid w-full max-w-page items-center gap-10 px-gutter py-section lg:grid-cols-12 lg:gap-14">
        <div className="min-w-0 lg:col-span-4">
          <img
            src={image.src}
            srcSet={srcSetOf(image.src)}
            sizes="(min-width: 1024px) 33vw, 100vw"
            alt={image.alt}
            loading="lazy"
            className="aspect-3/2 w-full rounded-lg bg-muted object-cover"
          />
        </div>
        <div className="min-w-0 lg:col-span-8">
          <h2 className="font-display text-h2 font-bold text-balance wrap-break-word">{title}</h2>
          {text ? (
            <p className="mt-4 max-w-text text-lead text-pretty text-muted-foreground">{text}</p>
          ) : null}
          <div className="mt-7 flex flex-col gap-4 sm:flex-row sm:items-center sm:flex-wrap">
            <a href={action.href} className={actionClass}>
              {action.label}
            </a>
            <a href={phoneHref} className={phoneClass}>
              {phone}
            </a>
          </div>
        </div>
      </div>
    </section>
  );
}
